def shell(title,body,file):
 nav=''.join(f'<a href="{f}">{t}</a> ' for f,t in links)
 bottom=''.join(f'<a href="{target}" '+('aria-current="page"' if label=='설정' else '')+f'><span>{icon}</span>{label}</a>' for icon,label,target in [('⌂','홈',links[0][0]),('▦','클래스',links[1][0]),('♧','상담',links[1][0]),('▤','대화',links[0][0]),('⚙','설정',links[0][0])])
 (p/file).write_text(f'<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{css}</style><body><aside><strong>MIND BREEZE</strong><a>⌂ 홈</a><a href="02-class-participants.html">▦ 클래스 관리</a><a>▤ 리포트</a><a class="active">⚙ 설정</a><small>운영 화면 디자인 시안</small></aside><div class="topbar">MIND BREEZE · 설정</div><main><div class="specimen">SDD-261 · 디자인 시안 / 이름·건수·시각은 모두 가상 예시 · 서버 연동 없음</div>{body}<div class="footer">시안 이동 · {nav}</div></main><nav class="bottom" aria-label="앱 메뉴">{bottom}</nav>{js}</body></html>')
