script='''<script>const data=ROWS;function render(){const q=document.querySelector('#q').value,s=document.querySelector('#status').value;let a=data.filter(r=>r.name.includes(q)&&(!s||r.state===s));if(document.querySelector('#group').value==='name')a.sort((a,b)=>a.name.localeCompare(b.name,'ko'));let last='';document.querySelector('#rows').innerHTML=a.map(r=>{let h='';if(document.querySelector('#group').value==='state'&&last!==r.state){last=r.state;h=`<tr class="group"><td colspan="7">${r.state}</td></tr>`}return h+`<tr><td>${r.name}</td><td>${r.state==='수집 제외'?'수집 제외':'수집 대상'}</td><td>${r.feature}창 수신</td><td>${r.raw}건 수신</td><td>${r.time}</td><td><span class="badge ${r.state==='확인 필요'?'warn':'purple'}">${r.state==='확인 필요'?'!':'↓'} ${r.state}</span></td><td><button aria-label="${r.name} 상세" aria-expanded="false" onclick="const d=this.closest('tr').nextElementSibling;d.hidden=!d.hidden;this.setAttribute('aria-expanded',String(!d.hidden))">펼치기 ⌄</button></td></tr><tr class="detail" hidden><td colspan="7"><strong>${r.reason}</strong><p>EEG ${r.raw}건 · PPG 0건 · ACC 0건 수신 / 전체 대조 미확인<br>마지막 수신 ${r.time} · 마지막 조회 14:32:08<br>리포트 입력 데이터 수신 · 리포트 선택: 선택 (예시)</p>TIP</td></tr>`}).join('');document.querySelector('#result').textContent=`조회 결과 ${a.length}명`;document.querySelector('#empty').hidden=!!a.length}render();</script>'''.replace('ROWS',json.dumps(rows,ensure_ascii=False)).replace('TIP',tip)
table='<section class="card"><div class="toolbar"><label class="grow">참여자 이름<input id="q" placeholder="이름 검색" oninput="render()"></label><label>상태<select id="status" onchange="render()"><option value="">전체 상태</option><option>확인 필요</option><option>수신 확인</option><option>수집 제외</option></select></label><label>그룹핑<select id="group" onchange="render()"><option value="state">상태별</option><option value="name">이름순</option></select></label></div></section><p id="result"></p><div class="tablewrap"><table><thead><tr><th>참여자</th><th>수집 대상</th><th>feature 수신</th><th>원시 수신</th><th>마지막 수신</th><th>확인 상태</th><th>상세</th></tr></thead><tbody id="rows"></tbody></table><p id="empty" hidden>조건에 맞는 참여자가 없어요.</p></div>'
